457	    public CompletableFuture<Void> commitAsync() {
458	        final long startTimeNanos = System.nanoTime();
459	        ensureActive();
460	        CompletableFuture<Void> checks = runCommitChecks();
461	        versionMutationCache.forEach((key, valuePair) ->
462	                transaction.mutate(valuePair.getLeft(), key, valuePair.getRight()));
463	        CompletableFuture<byte[]> versionFuture = transaction.getVersionstamp();
464	        long beforeCommitTimeMillis = System.currentTimeMillis();
465	        CompletableFuture<Void> commit = MoreAsyncUtil.isCompletedNormally(checks) ?
466	                                         delayedCommit() :
467	                                         checks.thenCompose(vignore -> delayedCommit());
468	        commit = commit.thenCompose(vignore -> {
469	            // The committed version will be -1 if the transaction is read-only,
470	            // in which case versionFuture has completed exceptionally with
471	            // transaction_read_only and thus can be ignored.
472	            committedVersion = transaction.getCommittedVersion();
473	            if (committedVersion > 0) {
474	                // The getVersionstamp() future can complete a tiny bit after the commit() future.
475	                return versionFuture.thenAccept(vs -> versionStamp = vs);
476	            } else {
477	                return AsyncUtil.DONE;
478	            }
479	        });
480	        if (config.isReportConflictingKeys()) {
481	            // Do this before the close (below).
482	            commit = MoreAsyncUtil.composeWhenCompleteAndHandle(commit, (v, ex) -> {
483	                final FDBException fdbException = FDBExceptions.getFDBCause(ex);
484	                if (fdbException != null && FDBError.fromCode(fdbException.getCode()) == FDBError.NOT_COMMITTED) {
485	                    return readConflictingKeys(ensureActive(), getExecutor()).thenApply(keys -> {
486	                        notCommittedConflictingKeys = keys;
487	                        return null;
488	                    });
489	                }
