491	            }, ex -> ex instanceof RuntimeException ? (RuntimeException)ex : new RecordCoreException(ex));
492	        }
493	        return commit.whenComplete((v, ex) -> {
494	            StoreTimer.Event event = FDBStoreTimer.Events.COMMIT;
495	            try {
496	                if (ex != null) {
497	                    event = FDBStoreTimer.Events.COMMIT_FAILURE;
498	                } else {
499	                    if (committedVersion > 0) {
500	                        if (database.isTrackLastSeenVersionOnCommit()) {
