1549	                                                                               @Nonnull Tuple primaryKey, boolean isDryRun) {
1550	        if (isDryRun) {
1551	            return loadTypedRecord(typedSerializer, primaryKey, false).thenCompose(oldRecord -> oldRecord == null ? AsyncUtil.READY_FALSE : AsyncUtil.READY_TRUE);
1552	        }
1553	        preloadCache.invalidate(primaryKey);
1554	        final RecordMetaData metaData = metaDataProvider.getRecordMetaData();
1555	        CompletableFuture<Boolean> result = loadTypedRecord(typedSerializer, primaryKey, false).thenCompose(oldRecord -> {
1556	            if (oldRecord == null) {
1557	                return AsyncUtil.READY_FALSE;
1558	            }
1559	            SplitHelper.deleteSplit(getRecordContext(), recordsSubspace(), primaryKey, metaData.isSplitLongRecords(), omitUnsplitRecordSuffix, true, oldRecord);
