1563	            final boolean oldHasIncompleteVersion = oldRecord.hasVersion() && !oldRecord.getVersion().isComplete();
1564	            if (useOldVersionFormat()) {
1565	                byte[] versionKey = getSubspace().pack(recordVersionKey(primaryKey));
1566	                if (oldHasIncompleteVersion) {
1567	                    context.removeVersionMutation(versionKey);
1568	                } else if (metaData.isStoreRecordVersions()) {
1569	                    ensureContextActive().clear(versionKey);
1570	                }
1571	            }
1572	            CompletableFuture<Void> updateIndexesFuture = updateSecondaryIndexes(oldRecord, null);
1573	            if (oldHasIncompleteVersion) {
1574	                return updateIndexesFuture.thenApply(vignore -> {
1575	                    byte[] versionKey = getSubspace().pack(recordVersionKey(primaryKey));
1576	                    context.removeLocalVersion(versionKey);
1577	                    return true;
